            cb.SetGlobalFloat(id_CombosBlightEnabled, CombosBlightEnabled.Value ? 1f : 0f);
            cb.SetGlobalFloat(id_CombosBlightStrength, CombosBlightStrength.Value);
            cb.SetGlobalVector(id_CombosBlightColor, CombosBlightColor.Value.linear);
            cb.SetGlobalFloat(id_CombosAllEnabled, CombosAllEnabled.Value ? 1f : 0f);
            cb.SetGlobalFloat(id_CombosAllStrength, CombosAllStrength.Value);
            cb.SetGlobalFloat(id_CombosAllGlow, CombosAllGlow.Value);
            cb.SetGlobalFloat(id_CombosAllCycleSpeed, CombosAllCycleSpeed.Value);
            cb.SetGlobalVector(id_CombosAllColor, CombosAllColor.Value.linear);
        }
    }
}
